package com.jigmnnaga.presentation.appointment.invite

import java.net.URI

/** Parses the invite URL generated by the backend without assuming an Android navigation route. */
object AppointmentInviteLinkParser {
    fun extractInviteCode(inviteUrl: String): String? {
        val uri = runCatching { URI(inviteUrl) }.getOrNull() ?: return null
        if (!uri.scheme.equals("https", ignoreCase = true)) return null
        if (!uri.host.equals(INVITE_HOST, ignoreCase = true)) return null

        val path = uri.path ?: return null
        val prefix = "/i/"
        if (!path.startsWith(prefix)) return null
        val inviteCode = path.removePrefix(prefix)
        if (inviteCode.isBlank() || '/' in inviteCode) return null
        return inviteCode
    }

    private const val INVITE_HOST = "jigeumnaga.app"
}
